WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CONTROL_DE_APRIETE_02' AND v.numero=1),d(t,o) AS (VALUES('CONTROL DE APRIETE - ALSTOM',1),('LISTA DE INSTRUMENTOS :',2),('OBSERVACIONES:',3),('PERSONAL:',4)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='CONTROL_DE_APRIETE_02' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),f AS (SELECT jsonb_agg(jsonb_build_object('coche',c,'bogie',b,'eje',n) ORDER BY n) x FROM unnest(ARRAY['MA1','MA1','MA1','MA1','MB1','MB1','MB1','MB1','MB3','MB3','MB3','MB3','R','R','R','R','MB2','MB2','MB2','MB2','MA2','MA2','MA2','MA2']) WITH ORDINALITY a(c,n) JOIN unnest(ARRAY['PB3','PB3','PB4','PB4','PB6','PB6','PB2','PB2','PB6','PB6','PB2','PB2','TB1','TB1','TB2','TB2','PB2','PB2','PB6','PB6','PB4','PB4','PB3','PB3']) WITH ORDINALITY b(b,n) USING(n)),d(t,c,e,ty,o,cf) AS (VALUES('CONTROL DE APRIETE - ALSTOM','fecha','FECHA:','fecha',1,'{}'),('CONTROL DE APRIETE - ALSTOM','puntos_apriete','CONTROL DE APRIETE - ALSTOM','tabla',2,jsonb_build_object('columnas',jsonb_build_array(jsonb_build_object('codigo','coche','etiqueta','COCHE'),jsonb_build_object('codigo','bogie','etiqueta','BOGIE/SERIE'),jsonb_build_object('codigo','eje','etiqueta','EJE'),jsonb_build_object('codigo','disco_freno','etiqueta','DISCO DE FRENO / 95 +/- 5 Nm'),jsonb_build_object('codigo','cubo_disco','etiqueta','CUBO DISCO DE FRENO / 50 Nm'),jsonb_build_object('codigo','cubo_rueda','etiqueta','CUBO DE RUEDA / 50 Nm'),jsonb_build_object('codigo','acople','etiqueta','ACOPLE ELASTICO / 69 Nm'),jsonb_build_object('codigo','motor','etiqueta','MOTOR DE TRACCION / 584 Nm'),jsonb_build_object('codigo','biela','etiqueta','BIELA DE REACCION / 390 Nm'),jsonb_build_object('codigo','tapa','etiqueta','TAPA TRASERA CAJA GRASA / 100 Nm'),jsonb_build_object('codigo','tope','etiqueta','TOPE REDUCTORA / 173 Nm'),jsonb_build_object('codigo','cable','etiqueta','CABLE LIBERACIÓN FRENO / 18 Nm'),jsonb_build_object('codigo','socalo','etiqueta','SOCALO NEUMATICO / 40 Nm')),'filasIniciales',(SELECT x FROM f))),('LISTA DE INSTRUMENTOS :','instrumentos','LISTA DE INSTRUMENTOS :','tabla',1,'{"columnas":[{"codigo":"codigo","etiqueta":"Código"},{"codigo":"descripcion","etiqueta":"Descripción"},{"codigo":"modelo","etiqueta":"Modelo / Marca"},{"codigo":"calibracion","etiqueta":"Fecha de Calibración"},{"codigo":"vencimiento","etiqueta":"Fecha de Vencimiento de Calibración"},{"codigo":"observaciones","etiqueta":"Observaciones"}],"filasIniciales":[{},{},{},{},{},{},{}]}'),('OBSERVACIONES:','observaciones','OBSERVACIONES:','texto',1,'{"multilinea":true}'),('PERSONAL:','tecnicos','TÉCNICOS','tabla',1,'{"columnas":[{"codigo":"tecnico","etiqueta":"TÉCNICO"},{"codigo":"firma","etiqueta":"FIRMA","tipo":"firma"}],"filasIniciales":[{"tecnico":"TÉCNICO A:"},{"tecnico":"TÉCNICO B:"},{"tecnico":"TÉCNICO C:"},{"tecnico":"TÉCNICO D:"},{"tecnico":"TÉCNICO E:"},{"tecnico":"TÉCNICO F:"},{"tecnico":"TÉCNICO G:"},{"tecnico":"TÉCNICO H:"},{"tecnico":"TÉCNICO I:"},{"tecnico":"TÉCNICO J:"},{"tecnico":"TÉCNICO K:"},{"tecnico":"TÉCNICO L:"},{"tecnico":"TÉCNICO M:"},{"tecnico":"TÉCNICO N:"},{"tecnico":"TÉCNICO O:"},{"tecnico":"TÉCNICO P:"},{"tecnico":"TÉCNICO Q:"},{"tecnico":"TÉCNICO R:"},{"tecnico":"TÉCNICO S:"},{"tecnico":"TÉCNICO T:"},{"tecnico":"TÉCNICO U:"},{"tecnico":"TÉCNICO V:"},{"tecnico":"TÉCNICO W:"},{"tecnico":"TÉCNICO X:"}]}'),('PERSONAL:','responsables','RESPONSABLES','tabla',2,'{"columnas":[{"codigo":"responsable","etiqueta":"RESPONSABLE"},{"codigo":"firma","etiqueta":"FIRMA","tipo":"firma"}],"filasIniciales":[{"responsable":"RESPONSABLE MTTO:"},{"responsable":"RESPONSABLE 01"},{"responsable":"RESPONSIBLE 02"},{"responsable":"RESPONSABLE 03"},{"responsable":"RESPONSABLE 04"}]}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
